import java.util.Objects;

final class TicketCode {
    private final String value;

    public TicketCode(String value) {
        this.value = Objects.requireNonNull(value, "Kód chybí");
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof TicketCode code)) {
            return false;
        }
        return value.equals(code.value);
    }

    @Override
    public int hashCode() {
        return value.hashCode();
    }

    @Override
    public String toString() {
        return "TicketCode[" + value + "]";
    }
}

public class Main {
    public static void main(String[] args) {
        TicketCode first = new TicketCode("A7");
        TicketCode second = new TicketCode("A7");
        System.out.println(first == second);      // false
        System.out.println(first.equals(second)); // true
        System.out.println(first);                // TicketCode[A7]
    }
}

exercises.solution:
Hodnota se normalizuje při vzniku a potom zůstává neměnná. Equals i hashCode čtou tentýž kód. Identita objektu ani referenční rovnost String nevyjadřují rovnost importované pozvánky.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    String x = in.nextLine(), y = in.nextLine();
    Invitation a = new Invitation(x), b = new Invitation(y);
    Set<Invitation> set = new HashSet<>();
    set.add(a);
    set.add(b);
    System.out.println("Rovne: " + a.equals(b));
    System.out.println("Pocet: " + set.size());
    System.out.println("Kopie nalezena: " + set.contains(new Invitation(x)));
    System.out.println("Rovno textu: " + a.equals(x));
  }
}

class Invitation {
  // UPRAVUJ ODSUD
  private final String code;

  Invitation(String code) {
    this.code = code.trim().toUpperCase(Locale.ROOT);
  }

  @Override
  public boolean equals(Object other) {
    return other instanceof Invitation i && code.equals(i.code);
  }

  @Override
  public int hashCode() {
    return code.hashCode();
  }
  // UPRAVUJ POTUD
}
```

Obě součásti identity patří do rovnosti i hashe. Objects.hash poskytuje jejich společný hash; jeho kolize jsou přípustné, rovnost proto vždy prověřuje oba skutečné údaje.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    String code = in.nextLine(), language = in.nextLine();
    Edition a = new Edition(code, language), b = new Edition(in.nextLine(), in.nextLine());
    Edition copy = new Edition(code, language);
    Set<Edition> set = new HashSet<>();
    set.add(a);
    set.add(b);
    System.out.println("Rovne: " + a.equals(b));
    System.out.println("Pocet: " + set.size());
    System.out.println("Kopie nalezena: " + set.contains(copy));
    System.out.println("Hash kopie: " + (a.hashCode() == copy.hashCode()));
  }
}

class Edition {
  // UPRAVUJ ODSUD
  private final String code, language;

  Edition(String code, String language) {
    this.code = code.trim();
    this.language = language.trim().toUpperCase(Locale.ROOT);
  }

  @Override
  public boolean equals(Object other) {
    return other instanceof Edition e && code.equals(e.code) && language.equals(e.language);
  }

  @Override
  public int hashCode() {
    return Objects.hash(code, language);
  }
  // UPRAVUJ POTUD
}
```
